def parse_price(s: str) -> float:
    # Remove dollar sign and split on comma
    s = s.replace('$', '').replace(',', '')
    # Split into whole number and decimal parts
    if '.' in s:
        whole, decimal = s.split('.')
    else:
        whole, decimal = s, ''
    # Pad decimal part with zeros if necessary
    decimal = decimal.ljust(2, '0')[:2]
    # Convert to float
    return float(f'{whole}.{decimal}')

